; ============================================================================
; Project127 — complete TR-DOS image, assembled in one SjASMPlus pass.
; Follows Project112's EMPTYTRD + SAVETRD build model.
; ============================================================================
        DEVICE ZXSPECTRUM128
        EMPTYTRD "disk_A.trd"
        INCLUDE "src/boot/p127_boot.asm"

; BASIC boot file is assembly data, not a Python-generated byte array.
        ORG     #B000
CLEAR       EQU #FD
LOAD        EQU #EF
CODE        EQU #AF
RANDOMIZE   EQU #F9
USR         EQU #C0
REM         EQU #EA
VAL         EQU #B0
OUT_CMD     EQU #DF

basic_loader:
; Line 10: initialize debug channel and reserve memory below #6000.
        DB      0,10
        DW      l10_end-l10
l10:
        DB      OUT_CMD,"239",#0E,#00,#00,#EF,#00,#00
        DB      ",","1",#0E,#00,#00,#01,#00,#00,":"
        DB      CLEAR,"24000",#0E,#00,#00,#5D,#C0,#00,#0D
l10_end:

; BASIC startup diagnostics.
        DB      0,11
        DW      l11_end-l11
l11:
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"91",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"80",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"49",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"50",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"55",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"93",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"32",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"66",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"65",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"83",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"73",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"67",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"32",34
        DB      #0D
l11_end:

; Exact TR-DOS interception sequence used by Project112/126.
        DB      0,20
        DW      l20_end-l20
l20:
        DB      RANDOMIZE,USR,"15619",#0E,#00,#00
        DW      15619
        DB      0,#3A,REM,#3A
        DB      "LOAD ",34,"P127BOOT",34," CODE 24576",#0D
l20_end:

; Output after TR-DOS has loaded the separate CODE file.
        DB      0,21
        DW      l21_end-l21
l21:
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"76",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"79",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"65",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"68",34,":"
        DB      OUT_CMD,VAL,34,"239",34,",",VAL,34,"32",34
        DB      #0D
l21_end:

        DB      0,30
        DW      l30_end-l30
l30:
        DB      OUT_CMD,"239",#0E,#00,#00,#EF,#00,#00,","
        DB      "2",#0E,#00,#00,#02,#00,#00,":"
        DB      RANDOMIZE,USR,VAL,34,"24576",34,#0D
l30_end:
        DB      #80
basic_loader_end:

        SAVETRD "disk_A.trd","boot.B",basic_loader,basic_loader_end-basic_loader,10

        ASSERT  p127_entry = #6000
        ASSERT  p127_end > p127_entry
        ASSERT  p127_end <= #A000
        ASSERT  basic_loader_end > basic_loader

; Project126 ATM console extension in the next resident memory window.
        PAGE 0
        ORG #A000
        INCLUDE "src/ui/p127_console.asm"
        INCLUDE "src/kernel/p127_physmem.asm"
        INCLUDE "src/kernel/p127_keyboard.asm"
p127_image_end:
        ASSERT p127_image_end <= #B000
        SAVETRD "disk_A.trd","P127BOOT.C",P127_LOAD_ADDRESS,p127_image_end-P127_LOAD_ADDRESS
